Given an array arr[] of non-negative numbers and a non-negative number k, find the number of subarrays having sum less than k. We may assume that there is no overflow.Examples :  Input: arr[] = [2, 5, 6], K = 10Output: 4Explanation: The subarrays are [2], [5], [6], and [2, 5]Input: arr[] = [1, 11, 2, 3, 15], K = 10Output: 4Explanation: The subarrays are [1], [2], [3], and [2, 3]Table of ContentNaive Approach - O(n²) Time and O(1) SpaceSliding Window - O(n) Time and O(1) SpaceNaive Approach - O(n²) Time and O(1) SpaceCheck every possible subarray and compute its sum. For each starting index, extend the subarray one element at a time and count it if the sum is less than K. Stop extending when the sum becomes greater than or equal to K since it will only increase further.Steps:Run a loop from 0 to n-1 to select the starting index of the subarrayFor each starting index, run another loop from i to n-1 to select the ending indexMaintain a variable sum to store the current subarray sumAdd elements one by one to sumIf sum < K, increment the countIf sum ≥ K, break the inner loop (since all elements are non-negative) 
            C++

    #include <vector>
using namespace std;

// Function to count subarrays having sum less than k
int countsubarray(vector<int> &arr, int k)
{
    int n = arr.size();
    int count = 0;

    // Pick starting point
    for (int i = 0; i < n; i++)
    {
        int sum = 0;

        // Pick ending point
        for (int j = i; j < n; j++)
        {
            // If sum is less than k, update sum and count
            if (sum + arr[j] < k)
            {
                sum += arr[j];
                count++;
            }
            else
            {
                break;
            }
        }
    }

    return count;
}

int main()
{
    vector<int> arr = {1, 11, 2, 3, 15};
    int k = 10;

    cout << countsubarray(arr, k);

    return 0;
}


