Output4Sliding Window - O(n) Time and O(1) SpaceThe idea of this approach is to use two pointers, start and end, to form a window (subarray). This window expands when we move end forward and shrinks when we move start forward, so that the sum of elements inside the window always remains less than K.StepsStart with start = 0, sum = 0, and count = 0Move end step by step and keep adding the current element to sumIf the sum becomes equal to or greater than K, remove elements from the beginning by subtracting arr[start] and moving start forwardKeep removing elements until the sum becomes less than K againNow the current window has sum less than KCount all subarrays that end at end by adding (end - start + 1) to count
            C++

    #include <vector>
using namespace std;

// Function to count subarrays having sum less than k
int countsubarray(vector<int> &arr, int k)
{
    int n = arr.size();
    int start = 0;
    int sum = 0;
    int count = 0;

    // Move end pointer
    for (int end = 0; end < n; end++)
    {
        sum += arr[end];

        // If sum becomes too large, shrink the window
        while (sum >= k)
        {
            sum -= arr[start];
            start++;
        }

        // Count valid subarrays ending at end
        count += (end - start + 1);
    }

    return count;
}

int main()
{
    vector<int> arr = {1, 11, 2, 3, 15};
    int k = 10;

    cout << countsubarray(arr, k);

    return 0;
}


